import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { test } from 'node:test';
import { normalizeStoredResponse } from '../src/evidence.js';
import type { CanonicalAnswers } from '../src/model.js';

// Independently authored synthetic API-shaped test doubles. These are NOT
// Typeform captures, and no expected value is generated by the local engine.
const selectedId = 'synthetic-response-01';
const submittedAt = '2026-10-31T04:00:00Z';
const options = { responseId: selectedId, unfiltered: true };
function definition(): any {
  const value = JSON.parse(readFileSync('tests/fixtures/synthetic-form.json', 'utf8'));
  value.id = 'synthetic-form-01';
  for (const field of value.fields) field.id = `source-${field.ref}`;
  for (const choice of value.fields[0].properties.choices) choice.id = `source-choice-${choice.ref}`;
  return value;
}
const text = (value: unknown = 'Synthetic respondent'): any => ({ type: 'text', field: { ref: 'contact', id: 'source-contact', type: 'short_text' }, text: value });
const number = (value: unknown = 500): any => ({ type: 'number', field: { ref: 'budget', id: 'source-budget', type: 'number' }, number: value });
const choice = (value: unknown = { label: 'No' }): any => ({ type: 'choice', field: { ref: 'request', id: 'source-request', type: 'multiple_choice' }, choice: value });
function capture(answers: any[] = [choice(), number(), text()]): any {
  return { total_items: 1, page_count: 1, items: [{ response_id: selectedId, submitted_at: submittedAt, answers }] };
}
function normalized(form: unknown, source: unknown, selected = options) {
  const result = normalizeStoredResponse(form, source, selected);
  assert.equal(result.ok, true, JSON.stringify(result));
  if (!result.ok) throw new Error('Synthetic projection unexpectedly rejected');
  return result;
}
function rejects(source: unknown, expected: 'FAIL' | 'BLOCKED' = 'FAIL', form: unknown = definition(), selected = options) {
  const result = normalizeStoredResponse(form, source, selected);
  assert.equal(result.ok, false, 'The source must not be silently normalized');
  if (result.ok) throw new Error('Unexpected projection success');
  assert.equal(result.status, expected);
  assert.ok(result.code.length && result.message.length);
  return result;
}
const canonical = (request: string, budget: CanonicalAnswers[number]['answer'], contact: string): CanonicalAnswers => [
  { field: 'request', answer: { presence: 'value', valueType: 'string', value: request } },
  { field: 'budget', answer: budget },
  { field: 'contact', answer: { presence: 'value', valueType: 'string', value: contact } },
];

test('stored projection preserves zero and empty string in definition order', () => {
  const result = normalized(definition(), capture([text(''), number(0), choice({ label: 'No' })]));
  assert.deepEqual(result.answers, canonical('no', { presence: 'value', valueType: 'number', value: 0 }, ''));
  assert.equal(result.responseId, selectedId);
  assert.equal(result.submittedAt, submittedAt);
  assert.equal(result.projectionVersion, 'typeform-stored-answers/1');
});

test('captured inactive answers remain present instead of being projected through the replacement route', () => {
  const result = normalized(definition(), capture([choice({ ref: 'no' }), number(500), text('Sample')]));
  assert.deepEqual(result.answers, canonical('no', { presence: 'value', valueType: 'number', value: 500 }, 'Sample'));
});

test('omitted answers become missing only inside a declared full completed answers array', () => {
  assert.deepEqual(normalized(definition(), capture([choice(), text('Sample')])).answers,
    canonical('no', { presence: 'missing' }, 'Sample'));
  assert.deepEqual(normalized(definition(), capture([])).answers,
    ['request', 'budget', 'contact'].map(field => ({ field, answer: { presence: 'missing' } })));
  rejects(capture([]), 'BLOCKED', definition(), { ...options, unfiltered: false });
  for (const absent of [undefined, null]) {
    const source = capture();
    if (absent === undefined) delete source.items[0].answers;
    else source.items[0].answers = absent;
    rejects(source, 'BLOCKED');
  }
  rejects(capture([null]), 'BLOCKED'); // API field filtering can yield null rows.
});

test('explicit null remains distinct from missing, empty string, and zero', () => {
  const result = normalized(definition(), capture([choice(), number(null), text(null)]));
  assert.deepEqual(result.answers, [
    { field: 'request', answer: { presence: 'value', valueType: 'string', value: 'no' } },
    { field: 'budget', answer: { presence: 'null' } },
    { field: 'contact', answer: { presence: 'null' } },
  ]);
});

test('projection preserves finite captured values outside local input constraints for later mismatch detection', () => {
  const outside = 'Synthetic text '.repeat(20); // Above the example form's 80-character limit.
  const result = normalized(definition(), capture([choice(), number(-0.25), text(outside)]));
  assert.deepEqual(result.answers, canonical('no', { presence: 'value', valueType: 'number', value: -0.25 }, outside));
});

test('explicit response selector chooses a matching response rather than the first or latest item', () => {
  const source = capture([choice({ label: 'Yes' }), number(10), text('selected')]);
  source.items.unshift({ response_id: 'synthetic-newer', submitted_at: '2026-10-31T04:01:00Z', answers: [choice(), number(99), text('wrong')] });
  source.total_items = 2;
  assert.deepEqual(normalized(definition(), source).answers,
    canonical('yes', { presence: 'value', valueType: 'number', value: 10 }, 'selected'));
  rejects(source, 'BLOCKED', definition(), { ...options, responseId: 'synthetic-absent' });
  rejects(source, 'FAIL', definition(), { ...options, responseId: '' });
  const duplicate = capture(); duplicate.items.push(structuredClone(duplicate.items[0]));
  rejects(duplicate);
});

test('incomplete or delayed responses cannot produce canonical missing answers', () => {
  rejects({ items: [], total_items: 0, page_count: 0 }, 'BLOCKED');
  const missingTimestamp = capture(); delete missingTimestamp.items[0].submitted_at;
  rejects(missingTimestamp, 'BLOCKED');
  for (const patch of [
    { submitted_at: null }, { submitted_at: '' },
    { response_type: 'partial' }, { response_type: 'started' }, { completed: false },
  ]) {
    const source = capture(); Object.assign(source.items[0], patch); rejects(source, 'BLOCKED');
  }
  const malformed = capture(); malformed.items[0].submitted_at = 'not-a-time';
  rejects(malformed);
});

test('raw definition IDs provide exact field fallback while conflicting or unknown identity fails', () => {
  const source = capture();
  for (const answer of source.items[0].answers) delete answer.field.ref;
  assert.deepEqual(normalized(definition(), source).answers,
    canonical('no', { presence: 'value', valueType: 'number', value: 500 }, 'Synthetic respondent'));
  for (const field of [
    { ref: 'budget', id: 'source-contact', type: 'number' },
    { ref: 'unknown', id: 'source-budget', type: 'number' },
    { ref: 'budget', id: 'unknown-id', type: 'number' },
    { ref: 'budget', id: 'source-budget', type: 'short_text' },
    { type: 'number' },
  ]) {
    const bad = capture(); bad.items[0].answers[1].field = field; rejects(bad);
  }
});

test('duplicate answers and duplicate source definition field or choice IDs are rejected', () => {
  rejects(capture([choice(), number(), number(), text()]));
  const duplicateFields = definition(); duplicateFields.fields[2].id = duplicateFields.fields[1].id;
  rejects(capture(), 'FAIL', duplicateFields);
  const duplicateChoices = definition(); duplicateChoices.fields[0].properties.choices[1].id = duplicateChoices.fields[0].properties.choices[0].id;
  rejects(capture(), 'FAIL', duplicateChoices);
});

test('single choices resolve by exact ref, source ID, or unique exact label', () => {
  for (const value of [
    { ref: 'yes' }, { id: 'source-choice-yes' }, { label: 'Yes' },
    { ref: 'yes', id: 'source-choice-yes', label: 'Yes' },
  ]) {
    assert.deepEqual(normalized(definition(), capture([choice(value), number(), text('Sample')])).answers,
      canonical('yes', { presence: 'value', valueType: 'number', value: 500 }, 'Sample'));
  }
  for (const value of [
    { label: 'yes' }, { label: ' Yes ' }, { ref: 'yes', id: 'source-choice-no' },
    { ref: 'yes', label: 'No' }, { id: 'source-choice-no', label: 'Yes' },
    { ref: 'yes', id: 'unknown' }, { ref: 'unknown', label: 'Yes' }, {},
  ]) rejects(capture([choice(value), number(), text()]));
  const ambiguous = definition(); ambiguous.fields[0].properties.choices[1].label = 'Yes';
  rejects(capture([choice({ label: 'Yes' }), number(), text()]), 'FAIL', ambiguous);
});

test('malformed or unsupported answer payloads do not silently discard source values', () => {
  for (const value of ['500', true, {}, [], Infinity, NaN]) rejects(capture([choice(), number(value), text()]));
  for (const value of [0, false, {}, []]) rejects(capture([choice(), number(), text(value)]));
  for (const answer of [
    { type: 'number', field: { ref: 'budget' } },
    { type: 'text', field: { ref: 'budget' }, text: '500' },
    { ...number(), text: 'concealed extra payload' },
    { ...number(), unknown_semantic_value: 42 },
    { ...choice(), choices: { labels: ['No'] } },
    { ...choice({ label: 'No', other: 'concealed value' }) },
    { type: 'choices', field: { ref: 'request' }, choices: { labels: ['No'] } },
    { type: 'file_url', field: { ref: 'contact' }, file_url: 'https://invalid.example/file' },
  ]) rejects(capture([answer]));
});

test('invalid collection and definition shapes fail without coercing a bare response into a capture', () => {
  for (const source of [null, [], 'capture', {}, { items: {} }, capture().items[0]]) rejects(source);
  for (const form of [null, {}, [], { title: 'Synthetic invalid form', fields: [] }]) rejects(capture(), 'FAIL', form);
});

test('public projection errors do not echo private answer values, identifiers, or input fragments', () => {
  const sentinel = 'PRIVATE_PROJECTION_SENTINEL_6943';
  const badNumber = capture([choice(), number({ token: sentinel }), text()]);
  const badField = capture([number()]); badField.items[0].answers[0].field = { ref: sentinel };
  const badChoice = capture([choice({ label: sentinel })]);
  const badForm = definition(); badForm.fields[0].type = sentinel;
  for (const [form, source] of [[definition(), badNumber], [definition(), badField], [definition(), badChoice], [badForm, capture()]]) {
    assert.equal(JSON.stringify(rejects(source, 'FAIL', form)).includes(sentinel), false);
  }
});
